  "nie je grupa": "grup değil",
  "nie je homomorfizmus": "homomorfizma değil",
  "nie je riešiteľná v radikáloch": "köklerle çözülemez",
  "obor integrity, ale nie pole": "tamlık bölgesi ama cisim değil",
  "odčítame ${@0}\\cdot({@1})$ a zostane ${@2}$": "${@0}\\cdot({@1})$ çıkarılır ve ${@2}$ kalır",
  "okruh s deliteľmi nuly": "sıfır bölenli halka",
  "pole": "cisim",
  "reducibilný": "indirgenebilir",
  "riešiteľná v radikáloch": "köklerle çözülebilir",
  "rád 1": "mertebe 1",
